import requests
import json

url = "https://partner.shopeemobile.com/api/v2/principal/get_content_affiliate_performance?access_token=access_token&partner_id=partner_id&principal_id=principal_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "content_list": [
    {
      "content_ids": [
        1388859,
        1388860
      ],
      "currency": "LOCAL",
      "shop_id": 181050132
    }
  ],
  "cursor": 0,
  "end_date": "2026-01-01",
  "granularity": "day",
  "page_size": 100,
  "start_date": "2026-01-01",
  "timezone": "GMT+8"
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

